84	function metrics = task005_observe_spectra(ppm, spectra, case_data)
85	mask = task005_reference_mask(ppm, case_data.reference_center_ppm, case_data.reference_width_ppm);
86	window = real(spectra(mask, :));
87	
88	polarities = zeros(1, columns(window));
89	for idx = 1:columns(window)
90	    polarities(idx) = task005_estimate_polarity(window(:, idx));
91	end
92	sign_consistency = mean(polarities == polarities(1));
93	
94	norms = zeros(1, columns(window));
95	for idx = 1:columns(window)
96	    norms(idx) = norm(window(:, idx));
97	end
98	retained = norm(mean(window, 2)) / max(mean(norms), 1e-12);
99	
100	metrics.reference_sign_consistency = sign_consistency;
101	metrics.retained_common_signal_ratio = retained;
102	metrics.reference_peak_polarity_consistent = all(polarities == polarities(1));
103	metrics.observations_finite = isfinite(sign_consistency) && isfinite(retained);
104	end
