116	Ncoils = 1; % SDAT already coil-combined
117	rawSubspecs = subspecs;
118	date = header.scan_date; % scan date [yyyy.mm.dd hh:mm:ss]
119	geometry.size.ap = header.ap_size; % voxel size in AP direction [mm]
120	geometry.size.lr = header.lr_size; % voxel size in LR direction [mm]
121	geometry.size.cc = header.cc_size; % voxel size in CC direction [mm]
122	geometry.pos.ap = header.ap_off_center; % voxel center offset in AP direction [mm]
123	geometry.pos.lr = header.lr_off_center; % voxel center offset in LR direction [mm]
124	geometry.pos.cc = header.cc_off_center; % voxel center offset in CC direction [mm]
125	geometry.rot.ap = header.ap_angulation; % angulation around AP axis [deg]
126	geometry.rot.lr = header.lr_angulation; % angulation around LR axis [deg]
127	geometry.rot.cc = header.cc_angulation; % angulation around CC axis [deg]
128	
129	% Produce specs
130	specs = fftshift(fft(fids,[],dims.t),dims.t);
131	% Calculate t and ppm arrays using the calculated parameters:
132	f = [(-spectralwidth/2)+(spectralwidth/(2*sz(1))):spectralwidth/(sz(1)):(spectralwidth/2)-(spectralwidth/(2*sz(1)))];
133	ppm = f/(Bo*42.577);
134	
135	% Philips data assumes the center frequency to be 4.68 ppm:
136	centerFreq = 4.68;
137	ppm=ppm + centerFreq;
138	
139	t = [0:dwelltime:(sz(1)-1)*dwelltime];
140	
141	%FILLING IN DATA STRUCTURE
142	out.fids=fids;
143	out.specs=specs;
144	out.sz=sz;
145	out.ppm=ppm;  
146	out.t=t;    
147	out.spectralwidth=spectralwidth;
148	out.dwelltime=dwelltime;
149	out.txfrq=txfrq;
150	out.date=date;
151	out.dims=dims;
152	out.Bo=Bo;
153	out.averages=averages;
154	out.rawAverages=rawAverages;
155	out.subspecs=subspecs;
156	out.rawSubspecs=rawSubspecs;
157	out.seq=sequence;
158	out.te=te;
159	out.tr=tr;
160	out.pointsToLeftshift=0;
161	out.centerFreq = centerFreq;
162	out.geometry = geometry;
163	if isfield(header,'nucleus')
164	    out.nucleus = header.nucleus;
165	end
166	if isfield(header,'equipment_sw_verions')
167	    out.software = ['R ' header.equipment_sw_verions];
168	end
169	%FILLING IN DATA STRUCUTRE FOR SDAT MRSI
170	if isfield(header, 'dim2_pnts')
171	    out.nXvoxels = header.dim2_pnts;
172	    out.flags.MultiVoxel=1;
173	end
174	if isfield(header, 'dim3_pnts')
175	    out.nYvoxels = header.dim3_pnts;
176	    out.flags.MultiVoxel=1;
177	end
178	if isfield(header, 'nr_of_slices_for_multislice') && isfield(header, 'dim2_pnts');
179	    out.nZvoxels = header.nr_of_slices_for_multislice;
180	    out.flags.MultiVoxel=1;
181	end
182	
183	%FILLING IN THE FLAGS
184	out.flags.writtentostruct=1;
185	out.flags.gotparams=1;
186	out.flags.leftshifted=0;
187	out.flags.filtered=0;
188	out.flags.zeropadded=0;
189	out.flags.freqcorrected=0;
190	out.flags.phasecorrected=0;
191	out.flags.averaged=0;
192	out.flags.addedrcvrs=1;
193	out.flags.subtracted=0;
194	out.flags.writtentotext=0;
195	out.flags.downsampled=0;
196	if out.dims.subSpecs==0
197	    out.flags.isFourSteps=0;
198	else
199	    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
200	end
201	if dims.extras > 0 % Is a series
202	   out.extras = out.sz(dims.extras);
203	   extra_names = {};
204	   seq = {};
205	   for ex = 1 : out.sz(dims.extras)
206	       extra_names{ex} = ['Exp_' num2str(ex)];
207	       seq{ex} = out.seq;
208	   end
209	   out.extra_names = extra_names;
210	   if dims.averages == 0
211	      out.averages=1;
212	      out.flags.averaged = 1;
213	   end
214	   out.spectralwidth = ones(1,out.extras)*spectralwidth;
215	   out.dwelltime = ones(1,out.extras)*dwelltime;
216	   out.txfrq = ones(1,out.extras)*txfrq;
217	   out.exp_var = ones(1,out.extras);
218	   out.seq = seq;
219	   out.te = ones(1,out.extras)*te;
220	   out.tr = ones(1,out.extras)*tr;
221	   out.pointsToLeftshift = zeros(1,out.extras);
222	   out.centerFreq = ones(1,out.extras)*centerFreq;   
223	   out.flags.isSeries = 1;
224	   out.flags.MultiVoxel=0;
225	end
226	% Add info for niiwrite
227	out.PatientPosition = strrep([header.patient_position ' ' header.patient_orientation],'"','');
228	out.Manufacturer = 'Philips';
229	[~,filename,ext] = fileparts(filename);
230	out.OriginalFile = [filename ext];
231	% Sequence flags
232	out.flags.isUnEdited = 0;
233	out.flags.isMEGA = 0;
234	out.flags.isHERMES = 0;
235	out.flags.isHERCULES = 0;
236	out.flags.isPRIAM = 0;
237	out.flags.isMRSI = 0;
238	%DONE

1	function [MRSCont] = osp_LoadSDAT(MRSCont)
2	%% [MRSCont] = osp_LoadSDAT(MRSCont)
3	%   This function reads raw (but coil-combined) data from Philips SDAT files.
4	%
5	%   USAGE:
6	%       [MRSCont] = osp_LoadSDAT(MRSCont);
7	%
8	%   INPUTS:
9	%       MRSCont     = Osprey MRS data container.
10	%
11	%   OUTPUTS:
12	%       MRSCont     = Osprey MRS data container.
13	%
14	%   AUTHOR:
15	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-20)
16	%       goeltzs1@jhmi.edu
17	%   
18	%   CREDITS:    
19	%       This code is based on numerous functions from the FID-A toolbox by
20	%       Dr. Jamie Near (McGill University)
21	%       https://github.com/CIC-methods/FID-A
22	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
23	%
24	%   HISTORY:
25	%       2019-02-20: First version of the code.
26	
27	% Close any remaining open figures
28	close all;
29	warning('off','all');
30	if MRSCont.flags.hasMM %re_mm adding functionality to load MM data
31	    if ((length(MRSCont.files_mm) == 1) && (MRSCont.nDatasets(1)>1))   %re_mm seems like specificy one MM file for a batch is also an option to plan to accomodate
32	        for kk=2:MRSCont.nDatasets(1) %re_mm 
33	            MRSCont.files_mm{kk} = MRSCont.files_mm{1}; % re_mm allowable to specify one MM file for the whole batch
34	        end %re_mm 
35	    end   %re_mm 
36	    if ((length(MRSCont.files_mm) ~= MRSCont.nDatasets(1)) )   %re_mm 
37	        msg = 'Number of specified MM files does not match number of specified metabolite files.'; %re_mm 
38	        fprintf(msg);
39	        error(msg);
40	    end   %re_mm 
41	end   %re_mm 
42	if MRSCont.flags.hasRef
43	    if length(MRSCont.files_ref) ~= MRSCont.nDatasets(1)
44	        msg = 'Number of specified reference files does not match number of specified metabolite files.'; %re_mm 
45	        fprintf(msg);
46	        error(msg);
47	    end
48	end
49	if MRSCont.flags.hasWater
50	    if length(MRSCont.files_w) ~= MRSCont.nDatasets(1)
51	        msg = 'Number of specified water files does not match number of specified metabolite files.'; %re_mm 
52	        fprintf(msg);
53	        error(msg);
54	    end
55	end
56	
57	%% Get the data (loop over all datasets)
58	refLoadTime = tic;
59	if MRSCont.flags.isGUI
60	    progressText = MRSCont.flags.inProgress;
61	else
62	    progressText = '';
63	end
64	for kk = 1:MRSCont.nDatasets(1)
65	     for ll = 1: 1:MRSCont.nDatasets(2)
66	        [~] = printLog('OspreyLoad',kk,ll,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);   
67	        if ~(MRSCont.flags.didLoad == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'raw') && (kk > length(MRSCont.raw))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
68	
69	            % Read in the raw metabolite data. Since the Philips SDAT loader needs
70	            % to know the number of sub-spectra (e.g. from spectral editing), the
71	            % type of sequence needs to be differentiated here already.
72	            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
73	            if MRSCont.flags.isUnEdited
74	                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},1,MRSCont.flags.isSERIES);
75	                raw.flags.isUnEdited = 1;
76	            elseif MRSCont.flags.isMEGA
77	                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},2,MRSCont.flags.isSERIES);
78	                raw.flags.isMEGA = 1;
79	            elseif MRSCont.flags.isHERMES
80	                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
81	                raw.flags.isHERMES = 1;
82	            elseif MRSCont.flags.isHERCULES
83	                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
84	                raw.flags.isHERCULES = 1;
85	            end
86	            % Add NIfTI-MRS information
87	            raw                           = osp_add_nii_mrs_field(raw,MRSCont.ver.Osp);
88	            MRSCont.raw{metab_ll,kk}      = raw;
89	
90	            % Read in the raw MM data. re_mm
91	            if MRSCont.flags.hasMM %re_mm
92	                temp_ll = MRSCont.opts.MultipleSpectra.mm(ll);
93	                if MRSCont.flags.isUnEdited %re_mm                    
94	                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
95	                    [raw_mm] = op_rmempty(raw_mm); %re_mm
96	                    raw_mm.flags.isUnEdited = 1;
97	                elseif MRSCont.flags.isMEGA %re_mm
98	                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},2,MRSCont.flags.isSERIES); %re_mm
99	                    raw_mm.flags.isMEGA = 1;
100	                elseif MRSCont.flags.isHERMES%re_mm
101	                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
102	                    raw_mm.flags.isHERMES = 1;
103	                elseif MRSCont.flags.isHERCULES %re_mm
104	                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
105	                    raw_mm.flags.isHERCULES = 1;
106	                end
107	                % Add NIfTI-MRS information
108	                raw_mm                      = osp_add_nii_mrs_field(raw_mm,MRSCont.ver.Osp);
109	                MRSCont.raw_mm{temp_ll,kk}  = raw_mm;
110	            end %re_mm      
111	
112	            % Read in the raw reference data.
113	            if MRSCont.flags.hasRef
114	                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
115	                if MRSCont.flags.isUnEdited                    
116	                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
117	                    raw_ref = op_combine_water_subspecs(raw_ref,0);
118	                    raw_ref.flags.isUnEdited = 1;
119	                elseif MRSCont.flags.isMEGA
120	                    try % GO 03042024: this works for the JHU patch only but throws an error for product MEGA
121	                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},2,MRSCont.flags.isSERIES);
122	                    catch % GO 03042024: this works for product MEGA
123	                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
124	                    end
125	                    raw_ref = op_combine_water_subspecs(raw_ref,0);
126	                    raw_ref.flags.isMEGA = 1;
127	                elseif MRSCont.flags.isHERMES
128	                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
129	                    raw_ref = op_combine_water_subspecs(raw_ref,0);
130	                    raw_ref.flags.isHERMES = 1;
131	                 elseif MRSCont.flags.isHERCULES
132	                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
133	                    raw_ref = op_combine_water_subspecs(raw_ref,0);
134	                    raw_ref.flags.isHERCULES = 1;
135	                end
136	                % Add NIfTI-MRS information
137	                raw_ref                     = osp_add_nii_mrs_field(raw_ref,MRSCont.ver.Osp);
138	                MRSCont.raw_ref{ref_ll,kk}  = raw_ref;
139	            end
140	            if MRSCont.flags.hasWater
141	                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
142	                raw_w   = io_loadspec_sdat(MRSCont.files_w{w_ll,kk},1,MRSCont.flags.isSERIES);
143	                raw_w = op_combine_water_subspecs(raw_w,0);
144	                raw_w.flags.isUnEdited = 1;
145	                % Add NIfTI-MRS information
146	                raw_w                     = osp_add_nii_mrs_field(raw_w,MRSCont.ver.Osp);
147	                MRSCont.raw_w{w_ll,kk}    = raw_w;
148	            end
149	
150	            % Read in the MM reference data.
151	            if MRSCont.flags.hasMMRef
152	                temp_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
153	                if MRSCont.flags.isUnEdited
154	                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
155	                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
156	                    raw_mm_ref.flags.isUnEdited = 1;
157	                elseif MRSCont.flags.isMEGA
158	                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},2,MRSCont.flags.isSERIES);
159	                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
160	                    raw_mm_ref.flags.isMEGA = 1;
161	                elseif MRSCont.flags.isHERMES
162	                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
163	                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
164	                    raw_mm_ref.flags.isHERMES = 1;
165	                 elseif MRSCont.flags.isHERCULES
166	                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
167	                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
168	                    raw_mm_ref.flags.isHERCULES = 1;
169	                end
170	                % Add NIfTI-MRS information
171	                raw_mm_ref                      = osp_add_nii_mrs_field(raw_mm_ref,MRSCont.ver.Osp);
172	                MRSCont.raw_mm_ref{temp_ll,kk}  = raw_mm_ref;
173	            end
174	        end
175	    end
176	end
177	time = toc(refLoadTime);
178	[~] = printLog('done',time,MRSCont.nDatasets(1),MRSCont.nDatasets(2),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI); 
179	% Set flag
180	MRSCont.flags.coilsCombined     = 1;
181	MRSCont.runtime.Load = time;
182	end

1	function [out] = osp_editSubSpecAlign(varargin)
2	%% [varargout] = osp_editSubSpecAlign(varargin)
3	%   Aligns sub-spectra of (multiplexed) edited MRS data to minimize
4	%   subtraction artefacts.
5	%
6	%   USAGE:
7	%       [outA, outB, outC, outD] = osp_editSubSpecAlign(in, seq, target,unstableWater);
8	%
9	%   INPUTS:
10	%       in        = Input data structure with sub-spectrum A.
11	%       seq       = sequence type
12	%       target     = String. Can be 'GABA' or 'GSH'. (necessary if only two
13	%                    inputs inA and inB are provided)
14	%       unstableWater = Flag for unstable residual water. This ignores
15	%                       water for the optimization and uses Choline instead
16	%
17	%   OUTPUTS:
18	%       outA       = Output following alignment of averages.
19	%       outB       = Output following alignment of averages.
20	%       outC       = Output following alignment of averages. (optional)
21	%       outD       = Output following alignment of averages. (optional)
22	%
23	%   AUTHOR:
24	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
25	%       goeltzs1@jhmi.edu
26	%       Dr. Mark Mikkelsen (Johns Hopkins University)
27	%       mmikkel5@jhmi.edu
28	%   
29	%   CREDITS:    
30	%       This code is based on numerous functions from the FID-A toolbox by
31	%       Dr. Jamie Near (McGill University)
32	%       https://github.com/CIC-methods/FID-A
33	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
34	%
35	%   HISTORY:
36	%       2019-08-15: First version of the code.
37	
38	
39	% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
40	if nargin == 5
41	    in     = varargin{1};
42	    seqType = varargin{2};
43	    target1 = varargin{3};
44	    target2 = varargin{4};
45	    unstableWater = varargin{5};
46	elseif nargin == 4 && (strcmp(varargin{2},'HERMES') || strcmp(varargin{2},'HERCULES'))
47	    in     = varargin{1};
48	    seqType = varargin{2};
49	    target1 = varargin{3};
50	    target2 = varargin{4};
51	    unstableWater = 0;
52	elseif nargin == 4
53	    in     = varargin{1};
54	    seqType = varargin{2};
55	    target = varargin{3};
56	    unstableWater = varargin{4};
57	elseif nargin == 3 && strcmp(varargin{2},'MEGA')
58	    in     = varargin{1};
59	    seqType = varargin{2};
60	    target  = varargin{3};
61	    unstableWater = 0;
62	else
63	    error('Error in osp_editSubSpecAlign! For provide raw data struct, the sequence type, the name of the editing target, and the optional unstable water flag.')
64	end
65	
66	% Check whether data is coil-combined. If not, throw error.
67	if ~in.flags.addedrcvrs
68	    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
69	end
70	
71	% Check whether data is averaged. If not, throw error.
72	if ~in.flags.averaged
73	    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
74	end
75	
76	switch seqType
77	   case 'MEGA'
78	        inA=op_takesubspec(in,1);
79	        inB=op_takesubspec(in,2);
80	    case 'HERMES'
81	        inA=op_takesubspec(in,1);
82	        inB=op_takesubspec(in,2);
83	        inC=op_takesubspec(in,3);
84	        inD=op_takesubspec(in,4);
85	    case 'HERCULES'
86	        inA=op_takesubspec(in,1);
87	        inB=op_takesubspec(in,2);
88	        inC=op_takesubspec(in,3);
89	        inD=op_takesubspec(in,4);
90	end
91	        
92	    
93	%%% 1. SET UP REQUIRED VARIABLES %%%
94	% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
95	% are to be minimized. Also, get a good starting estimate for the frequency
96	% alignment shift by determining the difference between the two maxima in
97	% the respective peak range (water, NAA, or Cho).
98	freq = inA.ppm;
99	% Water
100	freqLim(1,:) = freq <= 4.68+0.22 & freq >= 4.68-0.22;
101	[~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
102	freq2 = freq(freqLim(1,:));
103	maxFreq = freq2(i);
104	for jj = 1:2
105	    tmp(jj,:) = freq <= maxFreq(jj)+0.22 & freq >= maxFreq(jj)-0.22;
106	end
107	freqLim(1,:) = or(tmp(1,:), tmp(2,:));
108	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
109	x0(1,:) = [f0 0];
110	    
111	% NAA
112	freqLim(2,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
113	peaks = '2.01 ppm (A/B)';
114	switch seqType
115	    case 'HERCULES'
116	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
117	    case 'HERMES'
118	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
119	    case 'MEGA'
120	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inB.specs(freqLim(2,:))))]);
121	end
122	freq2 = freq(freqLim(2,:));
123	maxFreq = freq2(i);
124	for jj = 1:2
125	    tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
126	end
127	freqLim(2,:) = or(tmp(1,:), tmp(2,:));
128	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
129	x0(2,:) = [f0 0];
130	
131	% In case the water peak is not well-behaved and has several peaks we are
132	% possibly detecting several peaks. This will lead to unreasonable shifts
133	% between the sub-spectra. In this case, we use the Choline peak.
134	if unstableWater
135	
136	    freqLim(1,:) = freq <= 3.22+0.09 & freq >= 3.22-0.09;
137	    [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
138	    freq2 = freq(freqLim(1,:));
139	    maxFreq = freq2(i);
140	    for jj = 1:2
141	        tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
142	    end
143	    freqLim(1,:) = or(tmp(1,:), tmp(2,:));
144	    f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
145	    x0(1,:) = [f0 0];
146	
147	end
148	
149	% Optimization options
150	lsqnonlinopts = optimoptions(@lsqnonlin);
151	lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');
152	
153	% Initialize common variables
154	t           = inA.t;
155	
156	
157	%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
