194	function out = objFunc(in1, in2, freqLim, t, x)
195	
196	% This is the objective function that minimizes the absolute sum of the difference over the 
197	% frequency range (freqLim) between the target spectrum (in1) and the 
198	% spectrum that is to be frequency-and-phase aligned (in2).
199	
200	f   = x(1); % frequency correction
201	phi = x(2); % phase correction
202	
203	y1 = in1.fids;
204	y2 = in2.fids .* exp(1i*pi*(t'*f*2+phi/180)); % apply to time-domain data
205	
206	% fft
207	a = real(fftshift(fft(y1,[],1),1));
208	b = real(fftshift(fft(y2,[],1),1));
209	
210	% return difference vector over defined frequency range
211	DIFF = a - b;
212	out = sum(abs(DIFF(freqLim)));
213	
214	end
