1	% op_combinesubspecs.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_combinesubspecs(in,mode);
6	% 
7	% DESCRIPTION:
8	% Combine the subspectra in an acquisition either by addition or
9	% subtraction.
10	% 
11	% INPUTS:
12	% in        = input data in matlab structure format.
13	% mode      = -"diff" adds the subspectra together (this is counter intuitive,
14	%             but the reason is that many "difference editing" sequences use phase
15	%             cycling of the readout ADC to achieve "subtraction by addition".
16	%             -"summ" performs a subtraction of the subspectra.
17	%
18	% OUTPUTS:
19	% out       = Output following combination of subspectra.  
20	
21	function out=op_combinesubspecs(in,mode);
22	
23	if in.flags.subtracted
24	    error('ERROR:  Subspectra have already been combined!  Aborting!');
25	end
26	if in.flags.isFourSteps
27	    error('ERROR: data with four steps must first be converted using op_fourStepCombine.m!  Aborting!');
28	end
29	
30	% if ~in.flags.freqcorrected
31	%     disp('WARNING:  Frequency correction has not yet been performed!');
32	% end
33	% if ~in.flags.phasecorrected
34	%     disp('WARNING:  Phase correction has not yet been performed!');
35	% end
36	
37	
38	if mode=='diff'
39	    %add the spectrum along the subSpecs dimension;
40	    fids=sum(in.fids,in.dims.subSpecs);
41	    fids=fids/in.sz(in.dims.subSpecs); %divide by number of subspecs so that this is an averaging operation;
42	elseif mode=='summ'
43	    %subtract the spectrum along the subSpecs dimension;
44	    fids=diff(in.fids,1,in.dims.subSpecs);
45	    fids=fids/in.sz(in.dims.subSpecs); %divide by nymber of subspecs so that this is an averaging operation;
46	end
47	
48	fids=squeeze(fids);
49	
50	%re-calculate Specs using fft
51	specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
52	
53	%change the dims variables
54	if in.dims.t>in.dims.subSpecs
55	    dims.t=in.dims.t-1;
56	else
57	    dims.t=in.dims.t;
58	end
59	if in.dims.coils>in.dims.subSpecs
60	    dims.coils=in.dims.coils-1;
61	else
62	    dims.coils=in.dims.coils;
63	end
64	if in.dims.averages>in.dims.subSpecs
65	    dims.averages=in.dims.averages-1;
66	else
67	    dims.averages=in.dims.averages;
68	end
69	dims.subSpecs=0;
70	if in.dims.extras>in.dims.subSpecs
71	    dims.extras=in.dims.extras-1;
72	else
73	    dims.extras=in.dims.extras;
74	end
75	
76	%re-calculate the sz variable
77	sz=size(fids);
78	
79	
80	%FILLING IN DATA STRUCTURE
81	out=in;
82	out.fids=fids;
83	out.specs=specs;
84	out.sz=sz;
85	out.dims=dims;
86	out.subspecs=1;
87	out.averages=in.averages/2;
88	
89	%FILLING IN THE FLAGS
90	out.flags=in.flags;
91	out.flags.writtentostruct=1;
92	out.flags.subtracted=1;

1	% op_takesubspec.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_takesubspec(in,index);
6	% 
7	% DESCRIPTION:
8	% Extract the subspectra with indices corresponding to the 'index' input
9	% array. 
10	% 
11	% INPUTS:
12	% in     = input data in matlab structure format.
13	% index  = vector indicating the indices of the subspectra you would like 
14	%          to extract.
15	%
16	% OUTPUTS:
17	% out    = Output dataset consisting of subspectra indices extracted from 
18	%          the input.
19	
20	function out=op_takesubspec(in,index);
21	
22	if ~isnumeric(index)
23	    index = find(strcmp(in.names,index));
24	    if isempty(index)
25	        index = 1;
26	    end
27	end
28	
29	if in.flags.subtracted && ~strcmp(in.seq, 'SPECIAL')
30	    error('ERROR:  Subspectra have already been combined!  Aborting!');
31	end
32	% in.fids = squeeze(in.fids);
33	if in.dims.subSpecs==0
34	    %Can't take subspec because there are none:
35	    if index > 1
36	        error('ERROR:  There are no subspectra in this dataset!  Aborting!');
37	    else
38	        fids = in.fids;
39	    end
40	elseif in.dims.subSpecs==1
41	    %SHOULD NEVER HAPPEN (Time dimension should always be dim=1)
42	    error('ERROR:  dims.subSpecs==1.  This should never happen!  Aborting!');
43	elseif in.dims.subSpecs==2
44	    fids=in.fids(:,index,:,:,:);
45	elseif in.dims.subSpecs==3;
46	    fids=in.fids(:,:,index,:,:,:);
47	elseif in.dims.subSpecs==4;
48	    fids=in.fids(:,:,:,index,:,:,:);
49	elseif in.dims.subSpecs==5
50	    fids=in.fids(:,:,:,:,index,:,:,:);
51	end
52	
53	%re-calculate Specs using fft
54	specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
55	
56	%change the dims variables
57	if in.dims.t>in.dims.subSpecs && in.dims.subSpecs ~=0
58	    dims.t=in.dims.t-1;
59	else
60	    dims.t=in.dims.t;
61	end
62	if in.dims.coils>in.dims.subSpecs && in.dims.subSpecs ~=0
63	    dims.coils=in.dims.coils-1;
64	else
65	    dims.coils=in.dims.coils;
66	end
67	if in.dims.averages>in.dims.subSpecs && in.dims.subSpecs ~=0
68	    dims.averages=in.dims.averages-1;
69	else
70	    dims.averages=in.dims.averages;
71	end
72	if in.dims.extras>in.dims.subSpecs && in.dims.subSpecs ~=0
73	    dims.extras=in.dims.extras-1;
74	else
75	    dims.extras=in.dims.extras;
76	end
77	dims.subSpecs=0;
78	
79	%re-calculate the sz variable
80	sz=size(fids);
81	
82	
83	%FILLING IN DATA STRUCTURE
84	out=in;
85	out.fids=fids;
86	out.specs=specs;
87	out.sz=sz;
88	out.dims=dims;
89	if ~out.flags.averaged
90	    try
91	        out.averages = out.sz(out.dims.averages);
92	    catch
93	        out.averages = out.sz(2);
94	    end
95	end
96	out.subspecs=1;
97	if isfield(out, 'names')
98	    out.names = out.names(index);
99	end
100	%FILLING IN THE FLAGS
101	out.flags=in.flags;
102	out.flags.writtentostruct=1;
103	out.flags.isFourSteps=0;

1	% op_concatAverages.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_concatAverages(in1,in2);
6	% 
7	% DESCRIPTION:
8	% Concatenate two scans along the averages dimension.  Two scans with 50
9	% averages each will now look like a single scan with 100 averages.  For
10	% looping, it is possible to enter a blank structure as the first input.
11	% In this case, the function will simply return the second input.
12	% 
13	% INPUTS:
14	% in1    = first input in matlab structure format.
15	% in2    = second input in matlab structure format.
16	%
17	% OUTPUTS:
18	% out    = Output following concatenation of inputs along the 
19	%           averages dimension.  
20	
21	function out=op_concatAverages(in1,in2);
22	
23	
24	if isempty(fieldnames(in1)) %Check if the first argument to be a null string
25	    out=in2; %If so, return in2;
26	else
27	    if in1.dims.averages~=0 && in2.dims.averages~=0 && in1.dims.averages ~= in2.dims.averages
28	        %RULE:  Averages dimension must be the same for both inputs UNLESS one of
29	        %the inputs has an averages dimension of zero:
30	        error('averages dimensions must be the same for both inputs');
31	    end
32	    
33	    if in1.dims.averages==0 && in2.dims.averages==0
34	        dim=2;
35	    elseif in1.dims.averages==0
36	        dim=in2.dims.averages;
37	    elseif in2.dims.averages==0;
38	        dim=in1.dims.averages;
39	    else
40	        dim=in1.dims.averages;
41	    end
42	    
43	    fids=cat(dim,in1.fids,in2.fids);
44	    specs=cat(dim,in1.specs,in2.specs);
45	    sz=size(fids);
46	    
47	    %FILLING IN DATA STRUCTURE
48	    out=in1;
49	    out.fids=fids;
50	    out.specs=specs;
51	    out.sz=sz;
52	    out.averages=in1.averages+in2.averages;
53	    out.rawAverages=in1.rawAverages+in2.rawAverages;
54	    if in1.dims.averages==0
55	        out.dims.averages=dim;
56	    end
57	    
58	    %FILLING IN THE FLAGS
59	    out.flags=in1.flags;
60	    out.flags.writtentostruct=1;
61	    out.flags.averaged=0;
62	end
