function [x, fval] = sb_lm(fun, x0, lb, ub)
%TEST-ONLY SHIM: small damped Gauss-Newton (Levenberg-Marquardt)
%least-squares solver used to stand in for lsqnonlin/lsqcurvefit/nlinfit.
if nargin < 3 || isempty(lb)
    lb = [];
end
if nargin < 4 || isempty(ub)
    ub = [];
end
x = x0(:);
r = fun(x);
r = r(:);
f = sum(r.^2) / 2;
for it = 1:60
    J = sb_fdjac(fun, x, r);
    g = J.' * r;
    A = J.' * J;
    mu = 1e-6 * max(diag(A) + eps);
    solved = false;
    step = zeros(size(x));
    for inner = 1:12
        step = -((A + mu * eye(size(A))) \ g);
        xn = x + step;
        if ~isempty(lb)
            xn = max(xn, lb(:));
        end
        if ~isempty(ub)
            xn = min(xn, ub(:));
        end
        rn = fun(xn);
        rn = rn(:);
        fn = sum(rn.^2) / 2;
        if isfinite(fn) && fn < f
            x = xn;
            r = rn;
            f = fn;
            solved = true;
            break;
        end
        mu = mu * 10;
    end
    if ~solved || norm(step) < 1e-10 * (1 + norm(x))
        break;
    end
end
fval = f;
end

function J = sb_fdjac(fun, x, r0)
n = numel(x);
m = numel(r0);
J = zeros(m, n);
for j = 1:n
    h = 1e-6 * max(abs(x(j)), 1);
    xp = x;
    xp(j) = xp(j) + h;
    rp = fun(xp);
    J(:, j) = (rp(:) - r0(:)) / h;
end
end

function [x, resnorm] = lsqnonlin(fun, x0, lb, ub, opts)
%TEST-ONLY SHIM delegating to the local LM solver.
if nargin < 3 || isempty(lb)
    lb = [];
end
if nargin < 4 || isempty(ub)
    ub = [];
end
[x, resnorm] = sb_lm(@(b) fun(b), x0, lb, ub);
x = reshape(x, size(x0));
end

function [x, resnorm] = lsqcurvefit(fun, x0, xdata, ydata, lb, ub, opts)
%TEST-ONLY SHIM delegating to the local LM solver.
if nargin < 5 || isempty(lb)
    lb = [];
end
if nargin < 6 || isempty(ub)
    ub = [];
end
yy = ydata(:);
[x, resnorm] = sb_lm(@(b) fun(b, xdata)(:) - yy, x0, lb, ub);
x = reshape(x, size(x0));
end

function [beta, resid, Jacobian] = nlinfit(X, y, fun, beta0, opts)
%TEST-ONLY SHIM delegating to the local LM solver.
yy = y(:);
resfun = @(b) fun(b, X)(:) - yy;
[beta, ~] = sb_lm(resfun, beta0, [], []);
beta = reshape(beta, size(beta0));
resid = resfun(beta);
Jacobian = [];
end

