function f = check(name, ok)
if ok
    fprintf('PASS  %s\n', name);
    f = 0;
else
    fprintf('FAIL  %s\n', name);
    f = 1;
end
end

% -------------------------------------------------------------------------
function [consistency, retained_sum, suppression_diff, edited_ratio] = observe_mega(proc)
% Phase-rotation-invariant diagnostics for a processed MEGA struct with
% subspecs A, B, diff1, sum on the loader ppm axis.
ppm = proc.ppm(:);
specs = proc.specs;
crm = abs(ppm - 3.05) <= 0.18;
edm = abs(ppm - 2.31) <= 0.15;
A = specs(:, 1);
B = specs(:, 2);
d1 = specs(:, strcmp(proc.names, 'diff1'));
sm = specs(:, strcmp(proc.names, 'sum'));
wA = A(crm);
wB = B(crm);
consistency = real(wA' * wB) / max(norm(wA) * norm(wB), eps);
denom = max((norm(A(crm)) + norm(B(crm))) / 2, eps);
retained_sum = norm(sm(crm)) / 2 / denom;
suppression_diff = norm(d1(crm)) / 2 / denom;
edenom = max(norm(abs(sm(edm))) / 2, eps);
edited_ratio = (norm(abs(d1(edm))) / 2) / edenom;
end

% -------------------------------------------------------------------------
function [allpos, retained_sum] = observe_hermes(proc)
ppm = proc.ppm(:);
specs = proc.specs;
crm = abs(ppm - 3.05) <= 0.18;
w1 = specs(crm, 1);
allpos = true;
sigs = [];
for ss = 1:4
    ws = specs(crm, ss);
    s = real(ws' * w1) / max(norm(ws) * norm(w1), eps);
    sigs(end + 1) = s;
    if s < 0.99
        allpos = false;
    end
end
sm = specs(:, strcmp(proc.names, 'sum'));
denom = 0;
for ss = 1:4
    denom = denom + norm(specs(crm, ss));
end
denom = max(denom / 4, eps);
retained_sum = norm(sm(crm)) / 4 / denom;
end

% -------------------------------------------------------------------------
function pol = observe_unedited(proc)
crm = abs(proc.ppm(:) - 3.05) <= 0.18;
w = real(proc.specs(crm, 1));
[~, i] = max(abs(w));
pol = sign(w(i));
end

