89	function Lorentz = TwoLorentzModel(x,freq)
90	% CJE LorentzModel
91	% Lorentzian  = (1/pi) * (hwhm) / (deltaf^2 + hwhm^2) (Wolfram)
92	% Peak height of Lorentzian = 4 / (pi*hwhm)
93	% This defnition of the Lorentzian has Area = 1
94	%
95	% This model is adapted from Gannet3.1
96	
97	area = x(1);
98	hwhm = x(2);
99	f0 = x(3);
100	phase = x(4);
101	baseline0 = x(5);
102	baseline1 = x(6);
103	
104	Absorption = 1/(2*pi) * area * ones(size(freq)) .* hwhm ./ ((freq-f0).^2 + hwhm.^2)+ ...
105	    1/(2*pi) * area * x(7) * ones(size(freq)) .* hwhm ./ ((freq-f0-0.18).^2 + hwhm.^2);
106	
107	Dispersion = 1/(2*pi) * area * (freq-f0) ./ ((freq-f0).^2 + hwhm.^2) + ...
108	    1/(2*pi) * area * x(7) * (freq-f0-0.18) ./ ((freq-f0-0.18).^2 + hwhm.^2);
109	
110	Lorentz = Absorption*cos(phase) + Dispersion*sin(phase) ...
111	    + baseline0 + baseline1*(freq-f0);
112	end

