function m = nanmedian(X, dim)
%TEST-ONLY SHIM for statistics-package nanmedian (column-wise by default).
if nargin < 2
    if isvector(X)
        m = median(X(~isnan(X)));
        return;
    end
    dim = 1;
end
sz = size(X);
if dim == 1
    m = zeros(1, sz(2));
    for j = 1:sz(2)
        col = X(:, j);
        m(j) = median(col(~isnan(col)));
    end
else
    m = zeros(sz(1), 1);
    for j = 1:sz(1)
        row = X(j, :);
        m(j) = median(row(~isnan(row)));
    end
end
end

function tf = contains(str, pat)
%TEST-ONLY SHIM for MATLAB contains() on char arrays and cellstr.
if iscellstr(str) || iscell(str)
    tf = false(size(str));
    for k = 1:numel(str)
        tf(k) = ~isempty(strfind(str{k}, pat));
    end
elseif ischar(str)
    tf = ~isempty(strfind(str, pat));
else
    tf = false;
end
end

