function tf = contains(str, pat)
%TEST-ONLY SHIM for MATLAB contains() on char arrays and cellstr.
if iscell(pat)
    tf = false(size(str));
    for p = 1:numel(pat)
        tf = tf | contains(str, pat{p});
    end
    return;
end
if iscellstr(str) || iscell(str)
    tf = false(size(str));
    for k = 1:numel(str)
        thisStr = str{k};
        if ischar(thisStr)
            tf(k) = ~isempty(strfind(thisStr, pat, 'ForceCellOutput', false));
        end
    end
elseif ischar(str)
    tf = ~isempty(strfind(str, pat, 'ForceCellOutput', false));
else
    tf = false;
end
end

